          </label>)}
        </fieldset>}
        <fieldset className="use-fieldset">
          <legend>Prepare questions for a pharmacist</legend>
          <p>Select conversation topics to include. These choices stay on this page.</p>
          {(Object.keys(conversationTopics) as QuestionTopic[]).map(key=><label key={key} className="use-radio">
            <input type="checkbox" checked={topics.includes(key)} onChange={event=>setTopics(previous=>event.target.checked?[...previous,key]:previous.filter(item=>item!==key))}/>
            <span>{({age:'Age / child care',allergy:'Allergies',medicines:'Other medicines',pregnancy:'Pregnancy or breastfeeding',conditions:'Existing health conditions'})[key]}</span>
          </label>)}
        </fieldset>
        <button className="primary" disabled={antibioticExample&&!plan} onClick={()=>setReviewed(true)}>See what to consider <ArrowRight size={16}/></button>
        {antibioticExample&&!plan&&<p className="field-help">Choose how the medicine would be used first.</p>}
      </section>
      <section className="use-result" aria-label="Educational result">
        {reviewed?<><span className="eyebrow">Source-linked education</span>
          <h2 tabIndex={-1} ref={result}>{antibioticExample&&plan?usePlans[plan].title:'Ask for a medicine-safety review'}</h2>
          <p>Consider the following points with a pharmacist. Professional content review is pending.</p>
          {planPassage&&<div className="use-priority"><EvidenceCard id={planPassage}/></div>}
          {evidenceIds.map(id=><EvidenceCard key={id} id={id}/>)}
          {antibioticExample&&<div className="use-ai">
            <button className="secondary" disabled={busy} onClick={organise}><BookOpen size={16}/>{busy?'Organising evidence…':'Organise the evidence with AI'}</button>
            <p className="field-help">Only the example topic and public evidence are used. Your selected answers and conversation topics stay in the browser.</p>
            <p role="status">{aiStatus}</p>
          </div>}
          <div className="use-next"><h3>Take these questions with you</h3><ul>
            <li>Can you check what care is appropriate in this situation?</li>
            {topics.map(key=><li key={key}>{conversationTopics[key]}</li>)}
          </ul>
          {topics.includes('age')&&<p>{getPassage('children').text} <a href={getPassage('children').reference.url} target="_blank" rel="noreferrer">CDC guidance</a></p>}
          </div>
          <p className="use-urgent">{emergency}</p>
          <button className="text-button" onClick={()=>selectTopic(topic)}><RotateCcw size={15}/> Reset this example</button>
        </>:<div className="use-empty"><BookOpen size={38}/><h2>Why do you want to use it?</h2><p>Choose a situation and a possible action. The explanation will show the relevant public guidance and the questions you can bring to a pharmacist.</p></div>}
      </section>
    </div>
    <ResistanceLesson/>
  </section>;
}

import {groq} from '@/lib/groq';
import {allow,readBody,sameOrigin} from '@/lib/guard';
import {authorizeAI,operationalEvent} from '@/lib/availability';
import {parseEvidenceRequest,retrieveUseEvidence,validateEvidenceOrder,useTopics} from '@/lib/use-check';

export const runtime='nodejs';
export const maxDuration=30;

export async function POST(request:Request) {
  const headers={'Cache-Control':'no-store'};
  if(!sameOrigin(request)) return Response.json({error:'Origin rejected'},{status:403,headers});
  let body:unknown;
  try {body=await readBody(request);} catch {return Response.json({error:'Invalid request'},{status:400,headers});}
  const topic=parseEvidenceRequest(body);
  if(!topic) return Response.json({error:'Choose a listed education topic.'},{status:400,headers});
  const passages=retrieveUseEvidence(topic);
  const ids=passages.map(p=>p.id);
  const fallback=(notice:string)=>Response.json({mode:'source-based',passageIds:ids,notice},{headers});
  if(ids.length===1) return fallback('The source passage is available directly.');
  if(!allow(request.headers.get('x-forwarded-for')?.split(',')[0]??'local')) return fallback('Request limit reached.');
  const gate=await authorizeAI(request);
  if(!gate.ok) return fallback('AI is temporarily unavailable. All source passages remain available.');
  try {
    const raw=await groq(process.env.GROQ_TEXT_MODEL||'openai/gpt-oss-120b',[
      {role:'system',content:'Order the supplied public education passage IDs by relevance to the fictional learning topic. Return JSON with exactly {"passageIds":[all supplied unique IDs]}. Include every ID. Never write medical advice or new text.'},
      {role:'user',content:JSON.stringify({topic:useTopics[topic].example,passages:passages.map(({id,title,text})=>({id,title,text}))})}
    ],true);
    const passageIds=validateEvidenceOrder(raw,ids);
    operationalEvent('explain','success','ready');
    return Response.json({mode:'AI-organised source-based education',passageIds},{headers});
  } catch {
    operationalEvent('explain','fallback','provider_failure');
    return fallback('AI unavailable. All source passages remain visible.');
  }
}

// Next steps after a confirmed match: hand the user to NAFDAC checks and to a pharmacist.
// Plain functions only. Uses the confirmed record, never the scan, photo or product name.
type ConfirmedMedicine={ingredients:readonly string[];antibiotic:boolean};
export const greenbookUrl='https://greenbook.nafdac.gov.ng/';
export const genuineCheck={
 title:'Check the pack is genuine',
 steps:[
  {text:'Does your pack have a silver scratch panel? Scratch it and text the PIN to the number printed beside it. The text is free. The reply tells you if the pack is genuine.'},
  {text:'Find the NAFDAC (Nigeria\'s drug regulator) number on the box. Look it up in the ',link:{label:'NAFDAC Greenbook',url:greenbookUrl},after:'.'},
  {text:'If the reply says fake, or the box has no NAFDAC number, do not take it. Show it to a pharmacist and report it to NAFDAC.'}
 ],
 disclaimer:'ResistGuard cannot tell if a medicine is genuine. These checks come from NAFDAC.'
} as const;
export const pharmacistSection={
 title:'Send your questions to a pharmacist',
 text:'WhatsApp opens with three questions already typed. You choose who to send it to. No photo or name is included.',
 button:'Ask a pharmacist on WhatsApp'
} as const;
export function joinIngredients(names:readonly string[]){
 if(names.length<2)return names.join('');
 return `${names.slice(0,-1).join(', ')} and ${names[names.length-1]}`;
}
export function whatsAppMessage(medicine:ConfirmedMedicine){
 return [
  `Hello, I have a medicine that contains ${joinIngredients(medicine.ingredients)}. ResistGuard says it is ${medicine.antibiotic?'an antibiotic':'not an antibiotic'}.`,
  '',
  '1. Do I need this medicine for my illness?',
  '2. Is it safe with my other medicines, allergies or conditions?',
  '3. How should I take it, and for how long?'
 ].join('\n');
}
// Digits only, country code first, no leading zero. Anything else means "let the user pick a contact".
export function pharmacistNumber(raw:string|undefined){
 const digits=(raw??'').replace(/[\s+\-()]/g,'');
 return /^[1-9]\d{7,14}$/.test(digits)?digits:null;
}
export function whatsAppLink(medicine:ConfirmedMedicine,phone?:string){
 const number=pharmacistNumber(phone);
 return `https://wa.me/${number??''}?text=${encodeURIComponent(whatsAppMessage(medicine))}`;
}

